/**
 * The engine's own arithmetic, ported so the builder can show what a change
 * amounts to before anything runs.
 *
 * Every function names the Python it mirrors in simulation-service/app/events.
 * Nothing here is an approximation: `engine.test.ts` replays cases generated by
 * the Python engine itself and expects the same numbers. If the engine changes,
 * that test is what says the previews have drifted from it.
 *
 * Pure, and free of the twin: callers pass the populations, severities and
 * objects in, so the same functions serve the builder, the catalogue and tests.
 */

import type { SimEffect, SimSpatial, TemporalProfile } from "@/lib/platform-api";

export type LatLon = [number, number];

/** effects.py: TemporalProfile.magnitude_at */
export function magnitudeAt(p: TemporalProfile, t: number): number {
  const start = p.start;
  const end = Math.max(p.end != null ? p.end : p.start, p.start);
  if (t < start || (p.end != null && t > end)) return 0;
  if (p.shape === "step") return p.peak;
  if (p.shape === "ramp") return p.peak * Math.min(1, (t - start) / Math.max(1, end - start));
  if (p.shape === "pulse") return t === start ? p.peak : 0;
  const centre = p.peak_tick != null ? p.peak_tick : (start + end) / 2;
  const width = Math.max(1, (end - start) / 6 || 1);
  return p.peak * Math.exp(-((t - centre) ** 2) / (2 * width * width));
}

const R_EARTH = 6371.0088;
const rad = (d: number) => (d * Math.PI) / 180;

/** geo.py: distance_km, haversine. */
export function distanceKm(a: LatLon, b: LatLon): number {
  const lat1 = rad(a[0]), lon1 = rad(a[1]), lat2 = rad(b[0]), lon2 = rad(b[1]);
  const h = Math.sin((lat2 - lat1) / 2) ** 2 + Math.cos(lat1) * Math.cos(lat2) * Math.sin((lon2 - lon1) / 2) ** 2;
  return 2 * R_EARTH * Math.asin(Math.min(1, Math.sqrt(h)));
}

/** geo.py: Spatial.delay_steps, rounded down. */
export const delaySteps = (sp: SimSpatial, d: number) =>
  !sp.speed_km_per_step || sp.speed_km_per_step <= 0 ? 0 : Math.floor(d / sp.speed_km_per_step);

/** geo.py: Spatial.attenuation */
export function attenuation(sp: SimSpatial, d: number): number {
  if (sp.falloff === "none") return 1;
  const share = sp.radius_km && sp.radius_km > 0 ? Math.min(1, d / sp.radius_km) : d;
  const remaining = Math.max(0, 1 - share);
  return sp.falloff === "linear" ? remaining : remaining * remaining;
}

/** geo.py: Spatial.reaches */
export const reaches = (sp: SimSpatial, d: number) => sp.radius_km == null || d <= sp.radius_km;

/** effects.py: Effect.magnitude_for. A place with no coordinates is excluded, not assumed central. */
export function magnitudeFor(e: SimEffect, t: number, loc: LatLon | null): number {
  if (!e.spatial) return magnitudeAt(e.profile, t);
  if (!loc) return 0;
  const d = distanceKm(e.spatial.epicentre, loc);
  if (!reaches(e.spatial, d)) return 0;
  const shifted = t - delaySteps(e.spatial, d);
  if (shifted < 0) return 0;
  return magnitudeAt(e.profile, shifted) * attenuation(e.spatial, d);
}

/** effects.py: Event.active, the event's own window before distance is asked. */
export const active = (e: SimEffect, t: number) => magnitudeAt(e.profile, t) > 0;

/** effects.py: Effect.value_for. A ramp at half strength applies half the change, not half the operand. */
export function valueFor(e: SimEffect, t: number, loc: LatLon | null): number | null {
  if (typeof e.value === "string") return null;
  let m = magnitudeFor(e, t, loc);
  if (m <= 0) return null;
  m = Math.min(1, m);
  return e.op === "multiply" ? 1 - (1 - e.value) * m : e.value * m;
}
export const valueAt = (e: SimEffect, t: number) => valueFor({ ...e, spatial: null }, t, null);

export function wants1(e: SimEffect, dim: string, v: string): boolean {
  const c = (e.select as Record<string, string[] | undefined>)[dim] || [];
  return !c.length || c.includes(v);
}
export const wants = (e: SimEffect, dims: Record<string, string>) => Object.entries(dims).every(([d, v]) => wants1(e, d, v));
/** Whether this effect does anything here, this step. */
export const landsAt = (e: SimEffect, t: number, loc: LatLon | null) => active(e, t) && magnitudeFor(e, t, loc) > 0;

const byId = <T extends { id: string }>(a: T, b: T) => (a.id < b.id ? -1 : a.id > b.id ? 1 : 0);

/**
 * dynamics.py: Engine._resolve. `set`, then `multiply`, then `add`, each sorted
 * by id, never in list order; then clamped to the target's minimum.
 */
export function resolve(
  path: string,
  base: number,
  dims: Record<string, string>,
  loc: LatLon | null,
  t: number,
  effects: SimEffect[],
  minimum: number | null,
): number {
  const m = effects
    .filter((e) => e.target === path && active(e, t) && wants(e, dims) && valueFor(e, t, loc) !== null)
    .sort(byId);
  let out = base;
  for (const e of m) if (e.op === "set") out = valueFor(e, t, loc)!;
  for (const e of m) if (e.op === "multiply") out *= valueFor(e, t, loc)!;
  for (const e of m) if (e.op === "add") out += valueFor(e, t, loc)!;
  return minimum != null ? Math.max(minimum, out) : out;
}

/**
 * dynamics.py: Engine._arrivals. Summed across effects, a rate split evenly
 * across the severities it names, the net per (population, severity) never
 * below zero. Keys are `${population}|${severity}`.
 */
export function arrivalsAt(
  t: number,
  effects: SimEffect[],
  pops: { id: string; size: number }[],
  sevs: string[],
): Map<string, number> {
  const out = new Map<string, number>();
  for (const path of ["demand.incidence", "demand.volume"]) {
    for (const e of effects) {
      if (e.target !== path || !active(e, t)) continue;
      const v = valueAt(e, t);
      if (v === null || v === 0) continue;
      const hit = sevs.filter((a) => wants1(e, "acuity", a));
      if (!hit.length) continue;
      const each = v / hit.length;
      for (const p of pops) {
        if (!wants1(e, "population", p.id)) continue;
        const amount = path === "demand.incidence" ? each * (p.size / 1000) : each;
        for (const a of hit) out.set(`${p.id}|${a}`, (out.get(`${p.id}|${a}`) || 0) + amount);
      }
    }
  }
  for (const [k, v] of Array.from(out)) if (!(v > 0)) out.delete(k);
  return out;
}

/** Python's round(): half to even. `reach` is rounded with it. */
export function pyRound(x: number): number {
  const f = Math.floor(x), d = x - f;
  if (Math.abs(d - 0.5) < 1e-9) return f % 2 === 0 ? f : f + 1;
  return Math.round(x);
}

export interface PlainObject {
  id: string;
  type: string;
  /** The facility it hangs off, or null. */
  at: string | null;
  properties: Record<string, unknown>;
}

/**
 * objects.py: matching. Sorted by id; `reach` takes from the front (a share of
 * what matched, or a count) before distance is asked. The same objects on every
 * run, by design: a random draw would make two runs incomparable.
 */
export function matching(e: SimEffect, objects: PlainObject[]): { hits: PlainObject[]; pool: number } {
  let hits = objects.filter((o) => wants1(e, "object_type", o.type) && wants1(e, "facility", o.at ?? "")).sort(byId);
  const pool = hits.length;
  if (e.reach != null) {
    const take = e.reach < 1 ? pyRound(hits.length * e.reach) : Math.trunc(e.reach);
    hits = hits.slice(0, Math.max(0, Math.min(take, hits.length)));
  }
  return { hits, pool };
}

/** mechanics.py: a stay is read in whole steps, at least one. */
export const staySteps = (v: number) => Math.max(1, Math.trunc(v));
